import { spawnSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
const push = process.argv.includes('--push');
if (process.argv.slice(2).some(arg => arg !== '--push')) throw new Error('Usage: node scripts/build-bundle.mjs [--push]');
const sources = ['backend', 'frontend', 'cli'];
const bundle = resolve(root, 'bundle');
const trailers = 'Co-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\nCo-authored-by: OpenBot <335604065+openbotgit[bot]@users.noreply.github.com>';

function run(command, args, cwd = root, capture = false) {
  const result = spawnSync(command, args, {
    cwd, encoding: 'utf8', stdio: capture ? 'pipe' : 'inherit',
    shell: process.platform === 'win32' && command === 'npm',
  });
  if (result.error) throw result.error;
  if (result.status !== 0) throw new Error(`${command} ${args.join(' ')} failed (${result.status})\n${result.stderr || ''}`);
  return result.stdout?.trimEnd() || '';
}
const git = (args, cwd = root) => run('git', args, cwd, true);
const changed = cwd => git(['diff', '--cached', '--name-only'], cwd) !== '';
function commit(message, cwd) {
  if (!changed(cwd)) { console.log(`${cwd === bundle ? 'bundle' : 'main'} unchanged: nothing to commit`); return; }
  git(['-c', 'user.name=OpenBot', '-c', 'user.email=335604065+openbotgit[bot]@users.noreply.github.com',
    'commit', '-m', message, '-m', trailers], cwd);
}

if (git(['branch', '--show-current']) !== 'main') throw new Error('Run the bundle builder on main');
if (changed(root)) throw new Error('Superproject has staged work; commit it before building');
const status = git(['status', '--porcelain', '--untracked-files=normal']);
if (status.split('\n').filter(Boolean).some(line => ![...sources, 'bundle'].includes(line.slice(3)))) {
  throw new Error(`Superproject has unrelated local changes:\n${status}`);
}
for (const name of [...sources, 'bundle']) {
  const folder = resolve(root, name);
  if (existsSync(resolve(folder, '.git')) && git(['status', '--porcelain'], folder)) {
    throw new Error(`${name} has local changes; refusing to overwrite them`);
  }
}
run('git', ['submodule', 'update', '--init', '--remote', ...sources]);
run('git', ['submodule', 'update', '--init', 'bundle']);
const revisions = Object.fromEntries(sources.map(name => [name, git(['rev-parse', 'HEAD'], resolve(root, name))]));
console.log('Source revisions:', revisions);
run('npm', ['ci', '--no-fund'], resolve(root, 'frontend'));
run('npm', ['run', 'build', '--', '--progress=false'], resolve(root, 'frontend'));
const publicOutput = resolve(root, 'frontend', 'dist', 'snip-frontend', 'browser');
if (!existsSync(resolve(publicOutput, 'index.html'))) throw new Error('Missing frontend/dist/snip-frontend/browser/index.html');
run(process.execPath, [resolve(root, 'scripts', 'smoke.mjs')]);

// Only replace generated artifacts; preserve the submodule Git metadata.
rmSync(resolve(bundle, 'public'), { recursive: true, force: true });
mkdirSync(resolve(bundle, 'public'), { recursive: true });
cpSync(publicOutput, resolve(bundle, 'public'), { recursive: true });
for (const [source, file] of [['backend', 'server.js'], ['cli', 'cli.js']]) {
  writeFileSync(resolve(bundle, file), readFileSync(resolve(root, source, file)));
}
writeFileSync(resolve(bundle, '.env'), 'PUBLIC_DIR=./public\n');
writeFileSync(resolve(bundle, 'package.json'), `${JSON.stringify({
  name: 'snip-bundle', private: true, scripts: { start: 'bun server.js' },
}, null, 2)}\n`);
writeFileSync(resolve(bundle, 'Dockerfile'), `FROM oven/bun:1-alpine@sha256:4cf82f5686b196504fe119db3fcd9185b191f82ece82c40680e597228ec6070a
WORKDIR /app
COPY --chown=bun:bun . .
ENV PORT=3000 PUBLIC_DIR=./public
EXPOSE 3000
USER bun
CMD ["bun", "server.js"]
`);
writeFileSync(resolve(bundle, '.dockerignore'), '.git\n.gitignore\nnode_modules\nREADME.md\n');
writeFileSync(resolve(bundle, 'railway.json'), `${JSON.stringify({
  build: { builder: 'DOCKERFILE' },
  deploy: { healthcheckPath: '/api/links', healthcheckTimeout: 30 },
}, null, 2)}\n`);
writeFileSync(resolve(bundle, 'release.json'), `${JSON.stringify({ sources: revisions }, null, 2)}\n`);
writeFileSync(resolve(bundle, 'README.md'), '# Generated Snip release\n\nGenerated by scripts/build-bundle.mjs on main. Do not hand-edit.\n\nRun `bun start` for UI + API + redirects. CLI requires Node 20+ on the host; the Bun-only image does not include Node.\n');
run(process.execPath, [resolve(root, 'scripts', 'smoke.mjs'), '--bundle']);
git(['add', 'server.js', 'cli.js', 'public', '.env', 'package.json', 'Dockerfile',
  '.dockerignore', 'railway.json', 'release.json', 'README.md'], bundle);
commit('Generate verified Snip bundle', bundle);
git(['add', ...sources, 'bundle']);
commit('Pin generated bundle and source revisions', root);
if (push) {
  // Push even after a no-op build: earlier local-only runs may have unpublished commits.
  run('git', ['push', 'origin', 'HEAD:bundle'], bundle);
  run('git', ['push', 'origin', 'HEAD:main']);
}
